-- Resources content for Underwriting's fewer tabs (CLAUDE.md, "Resources
-- stay in step with the code"; docs/underwriting-traffic-redesign.md §17).
-- Content only; the schema changes are 20261001120000 and 20261001120100.

select private.rc_release_guide(
  p_slug => 'underwriting-dashboard',
  p_tool_key => 'underwriting',
  p_title => 'The dashboard',
  p_summary => 'What needs attention today, grouped by job: missed credits, scheduling, and affidavits.',
  p_screen_keys => array['underwriting.dashboard'],
  p_sort_order => 10,
  p_version_note => 'Grouped by job, with affidavit counts',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The dashboard opens on what needs attention, in three groups. Every number links to the list it counts, filtered the same way."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Missed credits"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Need a decision","marks":[{"type":"bold"}]},{"type":"text","text":": an exception with no makegood yet, or one the agency declined."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Waiting on the agency","marks":[{"type":"bold"}]},{"type":"text","text":": the order's makegoods need the agency's approval, and no answer is recorded yet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Makegoods awaiting a break","marks":[{"type":"bold"}]},{"type":"text","text":": the next auto-fill places these first."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Scheduling"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Units not yet scheduled","marks":[{"type":"bold"}]},{"type":"text","text":": open periods on active contracts that auto-fill hasn't reached yet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Capacity conflicts","marks":[{"type":"bold"}]},{"type":"text","text":": lines that can't be placed in the next 14 days, listed below with what's blocking each one."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Affidavits"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To generate","marks":[{"type":"bold"}]},{"type":"text","text":": contracts with aired credits not yet covered by an affidavit."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Awaiting your signature","marks":[{"type":"bold"}]},{"type":"text","text":": generated affidavits ready to sign. Only underwriting managers see this one."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Auto-fill everything","marks":[{"type":"bold"}]},{"type":"text","text":" in the right-hand column to fill every active contract's open periods, makegoods first."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'underwriting-exceptions-and-makegoods',
  p_tool_key => 'underwriting',
  p_title => 'Exceptions and makegoods',
  p_summary => 'When a credit misses, decide what happens, schedule the makegood, and let it close itself.',
  p_screen_keys => array['underwriting.exceptions'],
  p_sort_order => 40,
  p_version_note => 'Makegoods are part of Exceptions',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An exception appears the moment a host records an underwriting credit as missed or moved. There's nothing to check for: if a credit didn't air as scheduled, it's on this list."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The list"}]},{"type":"paragraph","content":[{"type":"text","text":"Each row is one missed credit, with its makegood beside it. The filters follow the steps of resolving a miss, and the list opens on the first one with anything in it:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Need a decision","marks":[{"type":"bold"}]},{"type":"text","text":": no makegood yet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Waiting on the agency","marks":[{"type":"bold"}]},{"type":"text","text":": the order says the agency approves makegoods, and it hasn't answered."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Makegood awaiting a break","marks":[{"type":"bold"}]},{"type":"text","text":": a makegood exists; auto-fill will place it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Makegood scheduled","marks":[{"type":"bold"}]},{"type":"text","text":": its break is chosen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Resolved","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"All","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Working an exception"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If the order needs the agency's approval, record its answer under "},{"type":"text","text":"Agency's answer","marks":[{"type":"bold"}]},{"type":"text","text":". Nothing schedules a makegood until then."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Under "},{"type":"text","text":"Makegood","marks":[{"type":"bold"}]},{"type":"text","text":", select "},{"type":"text","text":"Create a makegood","marks":[{"type":"bold"}]},{"type":"text","text":". The next auto-fill places it ahead of regular credits. To choose the break yourself, open "},{"type":"text","text":"Pick a break now","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Under "},{"type":"text","text":"Decide","marks":[{"type":"bold"}]},{"type":"text","text":", choose what happens: make it good, accept the alternate airing, waive, or close with no action. Rarer decisions are under "},{"type":"text","text":"More decisions","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An exception closes itself when its last makegood airs. There's no separate step to close it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A makegood counts toward the period the original credit missed, so it never counts as an extra unit."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Waiving a credit needs an underwriting manager."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A resolved exception can be reopened from its own page."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'underwriting-affidavits',
  p_tool_key => 'underwriting',
  p_title => 'Affidavits',
  p_summary => 'Generate each month''s affidavits, then sign them in order.',
  p_screen_keys => array['underwriting.affidavits'],
  p_sort_order => 50,
  p_version_note => 'One list per month',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Affidavits are one list per month, with a row for every contract that aired credits that month. A row's button shows where it stands: "},{"type":"text","text":"Generate","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"Sign","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"Signed","marks":[{"type":"bold"}]},{"type":"text","text":" with its PDF."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Each month"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open "},{"type":"text","text":"Affidavits","marks":[{"type":"bold"}]},{"type":"text","text":". It opens on last month."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Generate","marks":[{"type":"bold"}]},{"type":"text","text":" on one row, or "},{"type":"text","text":"Generate","marks":[{"type":"bold"}]},{"type":"text","text":" with a count at the top to do every row still waiting. A row that fails says why, and the rest still generate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Whoever signs selects "},{"type":"text","text":"Sign","marks":[{"type":"bold"}]},{"type":"text","text":" with a count at the top, then "},{"type":"text","text":"Sign and open next","marks":[{"type":"bold"}]},{"type":"text","text":" on each one. Previous and Skip move through the month without signing."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Signing"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your title on the signature line comes from your profile. Changing it while signing applies to that affidavit only. An administrator sets titles under Admin › Users."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Signing stores the PDF, and it can't be changed afterwards. A correction is a new affidavit; the list shows the earlier version beside it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only underwriting managers can sign. Everyone else sees “Waiting for signature” and can preview the draft."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use the arrows beside the month to see earlier months. A note at the top names any earlier month that still has affidavits to generate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For an unusual period, use "},{"type":"text","text":"Generate one by hand","marks":[{"type":"bold"}]},{"type":"text","text":" at the bottom of the list."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An affidavit lists only credits that aired."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'underwriting-setup',
  p_tool_key => 'underwriting',
  p_title => 'Setup',
  p_summary => 'Inventory pools, industries, and the one-time imports from RadioTraffic.',
  p_screen_keys => array['underwriting.setup'],
  p_sort_order => 60,
  p_version_note => 'Pools, industries and imports in one place',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Setup holds the lists the rest of the tool depends on. Each card says whether it needs attention."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inventory pools","marks":[{"type":"bold"}]},{"type":"text","text":": what an order's “AM Drive” or “Carpool” means in Log programs and time windows. A pool with no mapping can't be scheduled."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Industries","marks":[{"type":"bold"}]},{"type":"text","text":": the categories auto-fill uses to keep competing underwriters out of the same break."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Import agreements","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Import copy","marks":[{"type":"bold"}]},{"type":"text","text":": the one-time moves from RadioTraffic. Only administrators see these."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'underwriting-contract-page',
  p_tool_key => 'underwriting',
  p_title => 'The contract page',
  p_summary => 'Schedule, Copy, and Agreement: what airs, what''s read, and what was agreed.',
  p_screen_keys => array['underwriting.contract'],
  p_sort_order => 25,
  p_version_note => 'Three tabs',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A contract's page has three tabs."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Schedule"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each line of the order, with its progress. Switch to "},{"type":"text","text":"By date","marks":[{"type":"bold"}]},{"type":"text","text":" to see every placement in air order, filtered to upcoming, aired, or not aired."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"When the order changes, select "},{"type":"text","text":"Revise the schedule","marks":[{"type":"bold"}]},{"type":"text","text":". A draft revision shows as a banner; "},{"type":"text","text":"Review and activate","marks":[{"type":"bold"}]},{"type":"text","text":" shows exactly what it would clear before you confirm."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Flights, for orders grouped by event, are at the bottom of the tab."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Copy"}]},{"type":"paragraph","content":[{"type":"text","text":"The messages this contract runs, and how they rotate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Agreement"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The signed agreement."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The traffic policy, shown as read. Select "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" to change it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The contract's affidavits."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Its revision history."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-01-underwriting-fewer-tabs',
  p_tool_key => 'underwriting',
  p_released_on => '2026-10-01',
  p_title => 'Underwriting has fewer tabs',
  p_guide_slugs => array['underwriting-dashboard', 'underwriting-exceptions-and-makegoods', 'underwriting-affidavits', 'underwriting-setup', 'underwriting-contract-page'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Underwriting & Traffic has fewer tabs. Makegoods are part of Exceptions, and an exception now closes itself when its makegood airs. Pools, industries and the imports are under Setup. Affidavits are one list per month, and signing moves straight on to the next one. A contract's page has three tabs: Schedule, Copy, and Agreement."}]}]}$body$
);
